import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Use deterministic annealing followed by strict coordinate/pattern refinement."""
    rng = np.random.RandomState(42)

    # Radius-two hexagonal triangular-lattice cluster, with alternating
    # outer corners removed to obtain exactly sixteen distinct points.
    axial = []
    for q in range(-2, 3):
        for r in range(-2, 3):
            if max(abs(q), abs(r), abs(q + r)) <= 2:
                axial.append((q, r))
    corners = {(2, 0), (0, -2), (-2, 2), (-2, 0), (0, 2), (2, -2)}
    remove = {(2, 0), (-2, 2), (0, 2)}
    axial = [a for a in axial if a not in remove]
    points = np.array(
        [[q + 0.5 * r, (np.sqrt(3.0) / 2.0) * r] for q, r in axial],
        dtype=float,
    )

    def objective(x):
        delta = x[:, None, :] - x[None, :, :]
        ds = np.sum(delta * delta, axis=2)
        ds = ds[np.triu_indices(len(x), 1)]
        return float(np.min(ds) / np.max(ds))

    best = points.copy()
    best_value = objective(best)
    current = best.copy()
    current_value = best_value

    # Fixed-seed annealing with both local and coordinated proposals.
    for iteration in range(18000):
        fraction = iteration / 18000.0
        step = 0.42 * (1.0 - fraction) ** 1.35 + 0.006
        proposal = current.copy()

        if iteration % 19 == 0:
            proposal += rng.normal(scale=step * 0.32, size=proposal.shape)
        else:
            index = int(rng.randint(16))
            proposal[index] += rng.normal(scale=step, size=2)

        value = objective(proposal)
        temperature = 0.018 * (1.0 - fraction) ** 1.7 + 1.0e-7
        if value > current_value or rng.rand() < np.exp(
            (value - current_value) / temperature
        ):
            current = proposal
            current_value = value
            if value > best_value:
                best = proposal.copy()
                best_value = value

    # Deterministic decreasing-step pattern search, retaining only strict gains.
    for step in (0.20, 0.10, 0.05, 0.025, 0.0125, 0.00625, 0.003125):
        changed = True
        while changed:
            changed = False
            for index in range(16):
                for direction in (
                    np.array((1.0, 0.0)),
                    np.array((-1.0, 0.0)),
                    np.array((0.0, 1.0)),
                    np.array((0.0, -1.0)),
                ):
                    candidate = best.copy()
                    candidate[index] += step * direction
                    value = objective(candidate)
                    if value > best_value:
                        best = candidate
                        best_value = value
                        changed = True

            for direction in (
                np.array((1.0, 1.0)),
                np.array((1.0, -1.0)),
                np.array((-1.0, 1.0)),
                np.array((-1.0, -1.0)),
            ):
                candidate = best + step * direction
                value = objective(candidate)
                if value > best_value:
                    best = candidate
                    best_value = value
                    changed = True

    return np.asarray(best, dtype=float).reshape(16, 2)


